-        {}
-      );
-
-      const bracket = this.originalReferences.lastIndexOf("<");
-      if (bracket >= 0) {
-        allHdr += lazy.jsmime.headeremitter.emitStructuredHeader(
-          "in-reply-to",
-          this.originalReferences.substr(bracket),
-          {}
-        );
-      }
+    if (!this.headers) {
